  const w = m[3];
  let x;
  if (!w) work = '';
  else if ((x = /^(\w+) sets? of papers to mark, (\w+) ready to hand back\.$/i.exec(w))) work = '채점할 제출물 ' + koN(x[1]) + '묶음, 돌려줄 수 있는 제출물 ' + koN(x[2]) + '묶음.';
  else if ((x = /^(\w+) sets? of papers to mark\.$/i.exec(w))) work = '채점할 제출물 ' + koN(x[1]) + '묶음.';
  else if ((x = /^(\w+) sets? of papers ready to hand back\.$/i.exec(w))) work = '돌려줄 수 있는 제출물 ' + koN(x[1]) + '묶음.';
  else if (/^nothing waiting to be marked\.$/i.test(w)) work = '채점할 제출물이 없습니다.';
